{
  "name": "notify",
  "version": "0.3.0",
  "description": "Notifications that say what happened: a long turn finished (with its answer), a permission prompt or a question waiting, an Actions budget running low; on the desktop and, through Claude Code push, on your phone",
  "author": {
    "name": "Stanislav Kozachenko",
    "url": "https://github.com/StanislavKozachenko"
  },
  "homepage": "https://github.com/StanislavKozachenko/claude-mods/tree/main/plugins/notify",
  "repository": "https://github.com/StanislavKozachenko/claude-mods",
  "license": "MIT",
  "keywords": [
    "notifications",
    "toast",
    "desktop",
    "push",
    "mobile",
    "permission"
  ],
  "userConfig": {
    "desktop": {
      "type": "boolean",
      "title": "Desktop notifications",
      "description": "Show a native notification on the desktop of the machine Claude Code runs on",
      "default": true
    },
    "push": {
      "type": "boolean",
      "title": "Phone notifications",
      "description": "Also send each notification through Claude Code's own push: it reaches the Claude app on your phone when you are away from the terminal",
      "default": true
    },
    "done": {
      "type": "boolean",
      "title": "A long turn finished",
      "description": "Notify when a turn longer than the shortest turn below finishes, with the first line of the answer",
      "default": true
    },
    "permission": {
      "type": "boolean",
      "title": "A permission prompt is waiting",
      "description": "Notify when a permission prompt is still unanswered after the wait below",
      "default": true
    },
    "question": {
      "type": "boolean",
      "title": "A question is waiting",
      "description": "Notify when a question Claude asked is still unanswered after the wait below",
      "default": true
    },
    "budget": {
      "type": "boolean",
      "title": "An Actions budget is running low",
      "description": "With the ci-budget mod installed: notify when the repo owner's Actions usage reaches the percentage below, and again at 100%",
      "default": true
    },
    "budgetPercent": {
      "type": "number",
      "title": "Budget notification at (%)",
      "description": "Share of the included Actions minutes that triggers the budget notification",
      "default": 80
    },
    "minSeconds": {
      "type": "number",
      "title": "Shortest turn to notify about",
      "description": "A turn that finishes sooner sends no notification, in seconds",
      "default": 30
    },
    "permissionDelaySeconds": {
      "type": "number",
      "title": "Wait before notifying about a prompt",
      "description": "A permission prompt or question answered within this many seconds sends no notification",
      "default": 10
    },
    "speak": {
      "type": "boolean",
      "title": "Also read it aloud",
      "description": "Speak the notification with the system voice",
      "default": false
    }
  }
}
